const url = new URL(request.url)
const statusParam = url.searchParams.get('status')
const supplierIdParam = url.searchParams.get('supplier_id')
const searchParam = url.searchParams.get('search')
const pageParam = parseInt(url.searchParams.get('page') ?? '1', 10)
const limitParam = Math.min(parseInt(url.searchParams.get('limit') ?? '50', 10), 200)
const offset = (pageParam - 1) * limitParam

let query = supabase
  .from('purchase_orders')
  .select('*, suppliers(id, name), purchase_order_lines(id, total_cents)', { count: 'exact' })
  .eq('studio_id', member.studio_id)
  .order('created_at', { ascending: false })
  .range(offset, offset + limitParam - 1)

if (statusParam) {
  query = query.eq('status', statusParam as 'cancelled' | 'draft' | 'ordered' | 'partial' | 'received')
}
if (supplierIdParam) {
  query = query.eq('supplier_id', supplierIdParam)
}
if (searchParam) {
  query = query.ilike('order_number', `%${searchParam}%`)
}

const { data, error, count } = await query

if (error) {
  logger.error({ err: error }, 'purchase orders GET failed')
  return Response.json({ error: 'Failed to fetch purchase orders' }, { status: 500 })
}

// Derive line_count + lines_total_cents from the nested rows (no N+1).
const items = (data as POWithLineCount[] ?? []).map((po) => {
  const lines = po.purchase_order_lines ?? []
  return {
    ...po,
    line_count: lines.length,
    lines_total_cents: lines.reduce((sum, l) => sum + (l.total_cents ?? 0), 0),
  }
})

return Response.json({ data: items, count: count ?? 0 })

