import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import type { PlanTier } from '@/lib/billing/feature-gate'

const ParamsSchema = z.object({
  id: z.string().uuid(),
})

/** PATCH /api/inventory/purchase-orders/[id]/cancel
 *
 * Cancels a purchase order. Only senior roles (owner / admin / manager) may cancel.
 * Allowed only when current status is `draft` or `ordered`.
 * Returns `{ id, status: 'cancelled' }`.
 */
export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const rawParams = await params
  const parsedParams = ParamsSchema.safeParse(rawParams)
  if (!parsedParams.success) {
    return Response.json({ error: 'Invalid purchase order id' }, { status: 400 })
  }
  const { id } = parsedParams.data

  const ip = getClientIp(request)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return new Response('Unauthorized', { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return new Response('No studio membership', { status: 403 })

  // Only owner / admin / manager may cancel POs.
  if (!['owner', 'admin', 'manager'].includes(member.role)) {
    return new Response('Forbidden', { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const gate = requireFeature(plan, 'inventory')
  if (gate) return gate

  // Verify PO exists and belongs to this studio.
  const { data: po } = await supabase
    .from('purchase_orders')
    .select('id, status')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (!po) return Response.json({ error: 'Purchase order not found' }, { status: 404 })

  // Only draft or ordered can be cancelled.
  if (po.status !== 'draft' && po.status !== 'ordered') {
    const reason =
      po.status === 'cancelled'
        ? 'Purchase order is already cancelled'
        : 'Cannot cancel a purchase order that has been received or partially received'
    return Response.json({ error: reason }, { status: 409 })
  }

  const { error } = await supabase
    .from('purchase_orders')
    .update({ status: 'cancelled', updated_at: new Date().toISOString() })
    .eq('id', id)
    .eq('studio_id', member.studio_id)

  if (error) {
    logger.error({ err: error, poId: id }, 'purchase order cancel failed')
    return Response.json({ error: 'Failed to cancel purchase order' }, { status: 500 })
  }

  return Response.json({ id, status: 'cancelled' })
}

