// Year-to-date threshold — first moment of the current calendar year (UTC).
const yearStart = new Date(new Date().getUTCFullYear(), 0, 1).toISOString()

// Parallel fetch: suppliers + aggregated PO stats (no N+1).
const [suppliersRes, posRes] = await Promise.all([
  supabase
    .from('suppliers')
    .select('*, inventory_items(id)', { count: 'exact' })
    .eq('studio_id', member.studio_id)
    .eq('is_active', true)
    .order('name'),
  supabase
    .from('purchase_orders')
    .select('supplier_id, total_cents, ordered_at')
    .eq('studio_id', member.studio_id)
    .in('status', ['ordered', 'partial', 'received'])
    .not('supplier_id', 'is', null),
])

if (suppliersRes.error) {
  logger.error({ err: suppliersRes.error }, 'suppliers GET failed')
  return Response.json({ error: 'Failed to fetch suppliers' }, { status: 500 })
}
if (posRes.error) {
  logger.error({ err: posRes.error }, 'supplier PO stats fetch failed')
  return Response.json({ error: 'Failed to fetch supplier statistics' }, { status: 500 })
}

// Aggregate PO stats per supplier in JS — single pass.
const statsMap = new Map<string, SupplierPoStats>()
for (const po of posRes.data ?? []) {
  if (!po.supplier_id) continue
  const cur = statsMap.get(po.supplier_id) ?? { last_ordered_at: null, ytd_spent_cents: 0 }
  // Track latest ordered_at.
  if (po.ordered_at !== null && (cur.last_ordered_at === null || po.ordered_at > cur.last_ordered_at)) {
    cur.last_ordered_at = po.ordered_at
  }
  // Accumulate YTD spend (ordered_at within this calendar year).
  if (po.ordered_at !== null && po.ordered_at >= yearStart) {
    cur.ytd_spent_cents += po.total_cents ?? 0
  }
  statsMap.set(po.supplier_id, cur)
}

const data = (suppliersRes.data ?? []).map((s) => {
  const stats = statsMap.get(s.id) ?? { last_ordered_at: null, ytd_spent_cents: 0 }
  return {
    ...s,
    last_ordered_at: stats.last_ordered_at,
    ytd_spent_cents: stats.ytd_spent_cents,
  }
})

return Response.json({ data })
